class ZimmButton extends HTMLElement {
  static get observedAttributes() {
    return ['variant', 'size', 'label', 'disabled', 'inverse', 'icon', 'type', 'full-width'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const variant  = this.getAttribute('variant') || 'primary';

    if (variant === 'icon') {
      const icon      = this.getAttribute('icon') || '';
      const type      = this.getAttribute('type') || 'button';
      const label     = this.getAttribute('label') || icon;
      const disabled  = this.hasAttribute('disabled');
      const inv       = this.hasAttribute('inverse');
      const iconBase  = new URL('../icon/assets/', import.meta.url).href;
      const focusColor = inv ? 'var(--zimm-color-grey-white)' : 'var(--zimm-color-border-focus)';

      this.shadowRoot.innerHTML = `
        <style>
          :host { display: inline-block; }
          button {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: none;
            border: none;
            padding: 8px;
            cursor: pointer;
            transition: opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
          }
          button:hover:not(:disabled) { opacity: 0.6; }
          button:disabled { cursor: not-allowed; opacity: 0.4; }
          button:focus-visible {
            outline: 1px solid ${focusColor};
            outline-offset: 2px;
            border-radius: 2px;
          }

