import '../button/zimm-button.js';
import '../select/zimm-select.js';
import '../add-to-wishlist/zimm-add-to-wishlist.js';

class ZimmProductDetailOptions extends HTMLElement {
  static get observedAttributes() {
    return [
      'product-name', 'price', 'colour-name',
      'size-options', 'cta-label', 'boutique-href', 'boutique-label',
      'style-code', 'model-info',
    ];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback()                        { this._render(); }
  attributeChangedCallback(n, oldVal, newVal) { if (oldVal !== newVal) this._render(); }

  _render() {
    const productName   = this.getAttribute('product-name')    || '';
    const price         = this.getAttribute('price')           || '';
    const colourName    = this.getAttribute('colour-name')     || '';
    const sizeOptions   = this.getAttribute('size-options')    || '[]';
    const ctaLabel      = this.getAttribute('cta-label')       || 'ADD TO BAG';
    const boutiqueHref  = this.getAttribute('boutique-href')   || '#';
    const boutiqueLabel = this.getAttribute('boutique-label')  || 'FIND IN BOUTIQUE';
    const styleCode     = this.getAttribute('style-code')      || '';
    const modelInfo     = this.getAttribute('model-info')      || '';

    const commonCss = new URL('../../common.css', import.meta.url).href;
    this.shadowRoot.innerHTML = `
      <link rel="stylesheet" href="${commonCss}">
      <style>
        :host {
          display: block;
          font-family: var(--zimm-font-family-body);
          color: var(--zimm-color-text-default);
        }

        .name-row {
          display: flex;
          align-items: flex-start;
          justify-content: space-between;
          gap: var(--zimm-scale-s);
          margin-bottom: var(--zimm-scale-xs);
        }

        .product-name {
          margin: 0;
          font-family: var(--zimm-font-family-body);
          font-size: var(--zimm-font-size-base);
          font-weight: var(--zimm-font-weight-medium);
          text-transform: uppercase;
          letter-spacing: var(--zimm-font-letterspacing-xs);
          line-height: var(--zimm-font-lineheight-tight);
        }

        .price {
          margin: 0 0 var(--zimm-scale-m) 0;
          font-size: var(--zimm-font-size-base);
          font-weight: var(--zimm-font-weight-regular);
        }

        slot[name="description"]::slotted(*) {
          font-family: var(--zimm-font-family-body);
          font-size: var(--zimm-font-size-sm);
          line-height: var(--zimm-font-lineheight-relaxed);
          margin: 0;
        }

        .description {
          font-size: var(--zimm-font-size-sm);
          line-height: var(--zimm-font-lineheight-relaxed);
          margin-bottom: var(--zimm-scale-l);
        }

        .colour-label {
          margin: 0 0 var(--zimm-scale-s) 0;
          font-size: var(--zimm-font-size-sm);
        }

        .swatches {
          display: flex;
          gap: var(--zimm-scale-xs);
          margin-bottom: var(--zimm-scale-l);
        }

        .size-row {
          display: flex;
          align-items: flex-end;
          justify-content: space-between;
          gap: var(--zimm-scale-m);
          margin-bottom: var(--zimm-scale-l);
        }

        .size-select { flex: 1; }

        .size-link {
          font-family: var(--zimm-font-family-body);
          font-size: var(--zimm-font-size-sm);
          color: var(--zimm-color-text-default);
          text-decoration: underline;
          text-underline-offset: 2px;
          white-space: nowrap;
          padding-bottom: 8px;
          transition: color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }
        .size-link:hover { color: var(--zimm-color-link-hover); }

        .cta-row { margin-bottom: var(--zimm-scale-m); }

        .boutique-link {
          display: block;
          font-family: var(--zimm-font-family-body);
          font-size: var(--zimm-font-size-sm);
          font-weight: var(--zimm-font-weight-medium);
          text-transform: uppercase;
          letter-spacing: var(--zimm-font-letterspacing-xs);
          color: var(--zimm-color-text-default);
          text-decoration: underline;
          text-underline-offset: 2px;
          margin-bottom: var(--zimm-scale-l);
          transition: color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }
        .boutique-link:hover { color: var(--zimm-color-link-hover); }

        .accordions {
          border-top: 1px solid var(--zimm-color-border-default);
          margin-bottom: var(--zimm-scale-l);
        }

        .meta {
          padding-top: var(--zimm-scale-m);
          border-top: 1px solid var(--zimm-color-border-default);
        }

        .meta p {
          margin: 0 0 var(--zimm-scale-xs) 0;
          font-size: var(--zimm-font-size-xs);
          color: var(--zimm-color-text-muted);
          line-height: var(--zimm-font-lineheight-relaxed);
        }
        .meta p:last-child { margin-bottom: 0; }
      </style>

      <div class="name-row">
        <p class="product-name">${productName}</p>
        <zimm-add-to-wishlist></zimm-add-to-wishlist>
      </div>

      <p class="price">${price}</p>

      <div class="description">
        <slot name="description"></slot>
      </div>

      ${colourName ? `
        <p class="colour-label">Colour: ${colourName}</p>
        <div class="swatches"><slot name="swatches"></slot></div>
      ` : ''}

      <div class="size-row">
        <div class="size-select">
          <zimm-select placeholder="Size" options='${sizeOptions}'></zimm-select>
        </div>
        <a class="size-link" href="#">Find your size</a>
      </div>

      <div class="cta-row">
        <zimm-button variant="primary" size="large" label="${ctaLabel}" full-width></zimm-button>
      </div>

      <a class="boutique-link" href="${boutiqueHref}">${boutiqueLabel}</a>

      <div class="accordions">
        <slot name="accordions"></slot>
      </div>

      <div class="meta">
        ${modelInfo ? `<p>${modelInfo}</p>` : ''}
        ${styleCode ? `<p>Style Code: ${styleCode}</p>` : ''}
      </div>
    `;
  }
}

customElements.define('zimm-product-detail-options', ZimmProductDetailOptions);

